    35	/** The owner calls this only after exact hosting publication and PR policy admission. */
    36	export class PullRequestDraftCoordinator {
    37	  constructor(private readonly options: PullRequestDraftCoordinatorOptions) {}
    38	
    39	  async create(reportId: string): Promise<DraftRecord> {
    40	    const publication = this.options.publication(reportId);
    41	    if (!publication || publication.state !== "confirmed" || publication.reportId !== reportId ||
    42	        !validRevision(publication.candidateRevision)) throw new PullRequestError("publication_unavailable");
    43	    if (!this.options.policyRequiresPr(reportId)) throw new PullRequestError("draft_not_required");
    44	    const previous = this.options.effects.getByReportId(reportId);
    45	    const binding = this.options.binding(publication.projectId,
    46	      previous ? { id: previous.bindingId, revision: previous.bindingRevision } : undefined);
    47	    if (!binding || binding.projectId !== publication.projectId || (!previous && !binding.enabled)) {
    48	      throw new PullRequestError("pr_binding_unavailable");
    49	    }
    50	    const adapter = this.options.makeAdapter(binding);
    51	    const repository = await adapter.repository();
    52	    if (!sameRepository(repository, publication.repository) || repository.instanceId !== binding.instanceId ||
    53	        repository.nativeId !== binding.repositoryId) throw new PullRequestError("repository_mismatch");
    54	    const baseRef = previous?.baseRef ?? (await adapter.defaultBranch(repository)).ref;
    55	    const proposedEffectId = previous?.effectId ?? this.options.effectId();
    56	    const effect = this.options.effects.admit({ effectId: proposedEffectId,
    57	      reportId, projectId: publication.projectId, taskId: publication.taskId,
    58	      bindingId: binding.id, bindingRevision: binding.revision, repository,
    59	      headRef: publication.ref, headRevision: publication.candidateRevision,
    60	      baseRef, recordedAt: previous?.recordedAt ?? this.options.now() });
    61	    const existing = await adapter.findByBranches(repository, effect.headRef, effect.baseRef);
    62	    if (existing) return this.confirm(effect, existing);
    63	    // A retained intent may already have reached the provider. Polling can resume
    64	    // reconciliation, but never dispatch a second create on an unproven absence.
    65	    if (previous || effect.effectId !== proposedEffectId) {
    66	      this.options.effects.markUnknown(effect.effectId, this.options.now());
    67	      throw new PullRequestError("create_outcome_unknown");
    68	    }
    69	    let created: PullRequestObservation | null = null;
    70	    try {
    71	      created = await adapter.createDraft(repository, effect.headRef, effect.baseRef,
    72	        effect.headRevision, this.options.title(effect.taskId));
    73	    } catch {
    74	      created = await adapter.findByBranches(repository, effect.headRef, effect.baseRef).catch(() => null);
    75	    }
    76	    if (created) return this.confirm(effect, created);
    77	    this.options.effects.markUnknown(effect.effectId, this.options.now());
    78	    throw new PullRequestError("create_outcome_unknown");
    79	  }
    80	
    81	  private confirm(effect: DraftRecord, observed: PullRequestObservation): DraftRecord {
    82	    if (!sameRepository(observed.repository, effect.repository) ||
    83	        observed.head.ref !== effect.headRef || observed.base.ref !== effect.baseRef ||
    84	        observed.head.revision !== effect.headRevision || !observed.draft) {
    85	      throw new PullRequestError("draft_observation_mismatch");
    86	    }
    87	    return this.options.effects.confirm(effect.effectId, observed.nativeId, observed.head.revision, this.options.now());
    88	  }
    89	}
