    31	/** Owner-authorized draft-to-ready transition; uncertain retries only observe. */
    32	export class PullRequestReadyCoordinator {
    33	  constructor(private readonly options: PullRequestReadyCoordinatorOptions) {}
    34	
    35	  async markReady(candidate: AuthorizedReadyCandidate): Promise<ReadyRecord> {
    36	    await this.options.verifyAuthority(candidate);
    37	    const previous = this.options.effects.getByCandidate(candidate.bindingId, candidate.nativePrId, candidate.headRevision);
    38	    const proposedEffectId = previous?.effectId ?? (this.options.effectId?.() ?? randomUUID());
    39	    const intent = this.options.effects.admit({ ...candidate, effectId: proposedEffectId,
    40	      recordedAt: previous?.recordedAt ?? this.options.now() });
    41	    if (intent.state !== "preflight") return this.reconcile(intent);
    42	    const before = await this.options.adapter.read(intent.repository, intent.nativePrId);
    43	    if (!before) throw new PullRequestError("pr_missing");
    44	    validateObservation(before, intent.repository, intent.nativePrId);
    45	    if (!sameRepository(before.repository, intent.repository) || before.state !== "open" ||
    46	        before.head.revision !== intent.headRevision || before.base.ref !== intent.baseRef ||
    47	        before.base.revision !== intent.baseRevision) throw new PullRequestError("ready_identity_mismatch");
    48	    if (!before.draft) return this.options.effects.confirm(intent.effectId, this.options.now());
    49	    if (!this.options.effects.markDispatching(intent.effectId, this.options.now())) {
    50	      return this.reconcile(intent);
    51	    }
    52	    try {
    53	      const after = await this.options.adapter.markReady(intent.repository, intent.nativePrId, intent.headRevision);
    54	      if (this.readyIdentity(intent, after)) return this.options.effects.confirm(intent.effectId, this.options.now());
    55	    } catch { /* A response can be lost after the write; reconcile by read. */ }
    56	    return this.reconcile(intent);
    57	  }
