    60	    try {
    61	      const observed = await this.options.adapter.read(intent.repository, intent.nativePrId);
    62	      if (observed && this.readyIdentity(intent, observed)) {
    63	        return this.options.effects.confirm(intent.effectId, this.options.now());
    64	      }
    65	    } catch { /* An invalid or unreadable observation cannot confirm the effect. */ }
    66	    this.options.effects.markUnknown(intent.effectId, this.options.now());
    67	    throw new PullRequestError("ready_outcome_unknown");
    68	  }
