    71	    validateObservation(observed, intent.repository, intent.nativePrId);
    72	    return observed.state === "open" && !observed.draft &&
    73	      observed.head.revision === intent.headRevision && observed.base.ref === intent.baseRef &&
    74	      observed.base.revision === intent.baseRevision;
