    28	/** One merge effect for one owner-approved candidate; restart recovery only reads. */
    29	export class PullRequestMergeCoordinator {
    30	  constructor(private readonly options: PullRequestMergeCoordinatorOptions) {}
    31	
    32	  async merge(candidate: AuthorizedMergeCandidate): Promise<MergeRecord> {
    33	    await this.options.verifyAuthority(candidate);
    34	    const previous = this.options.effects.getByCandidate(candidate.bindingId, candidate.nativePrId, candidate.headRevision);
    35	    const proposedEffectId = previous?.effectId ?? (this.options.effectId?.() ?? randomUUID());
