    71	      created = await adapter.createDraft(repository, effect.headRef, effect.baseRef,
    72	        effect.headRevision, this.options.title(effect.taskId));
    73	    } catch {
    74	      created = await adapter.findByBranches(repository, effect.headRef, effect.baseRef).catch(() => null);
    75	    }
