     1	import { sameRepository, validBranchRef, validRevision, type RepositoryIdentity } from "../hosting/contract.js";
     2	
     3	/** Versioned, provider-neutral owner boundary. A PR is not a hosting or CI grant. */
     4	export const PULL_REQUEST_CONTRACT_VERSION = 1;
     5	
     6	export interface PullRequestRef {
     7	  repository: RepositoryIdentity;
     8	  ref: string;
     9	  revision: string;
    10	}
    11	
    12	export interface PullRequestReview {
    13	  nativeId: string;
    14	  actor: { nativeId: string; login: string; kind: "human" | "bot" | "unknown" };
    15	  decision: "approved" | "changes_requested" | "commented" | "pending";
    16	  headRevision: string;
    17	  dismissed: boolean;
    18	  stale: boolean;
    19	  submittedAt: string;
    20	}
    21	
    22	export interface PullRequestObservation {
    23	  repository: RepositoryIdentity;
    24	  nativeId: string;
    25	  head: PullRequestRef;
    26	  base: PullRequestRef;
    27	  state: "open" | "closed" | "merged";
    28	  draft: boolean;
    29	  mergeable: boolean | null;
    30	  mergeStrategy: "fast-forward-only" | "other" | "unknown";
    31	  requiredChecks: Array<{ context: string; state: "success" | "failure" | "pending" | "unknown" }>;
    32	  advisoryChecks?: Array<{ context: string; state: "success" | "failure" | "pending" | "unknown" }>;
    33	  queuedMerge?: "none" | "queued" | "unknown";
    34	  requiredApprovals: number;
    35	  reviews: PullRequestReview[];
    36	  discussionCount: number;
    37	  /** Provider-native update or conflict token. It cannot substitute for head identity. */
    38	  providerRevision: string;
    39	  mergedRevision?: string;
    40	  url?: string;
    41	}
    42	
    43	export interface PullRequestAdapter {
    44	  read(repository: RepositoryIdentity, nativeId: string): Promise<PullRequestObservation | null>;
    45	  mergeFastForward(repository: RepositoryIdentity, nativeId: string, exactHead: string): Promise<void>;
    46	}
    47	
    48	export interface ExactMergeRequest {
    49	  repository: RepositoryIdentity;
    50	  nativeId: string;
    51	  headRevision: string;
    52	  baseRef: string;
    53	  baseRevision: string;
    54	  strategy: "fast-forward-only";
    55	  requiredHumanActorId: string;
    56	}
    57	
    58	export class PullRequestError extends Error {
    59	  override readonly name = "PullRequestError";
    60	  constructor(readonly code: string) { super(code); }
    61	}
    62	
    63	/** The owner must persist merge intent before calling this function. */
    64	export async function requestExactMerge(adapter: PullRequestAdapter, request: ExactMergeRequest): Promise<PullRequestObservation> {
    65	  if (!request.nativeId || request.nativeId.length > 256 || !validRevision(request.headRevision) ||
    66	      !validBranchRef(request.baseRef) || !validRevision(request.baseRevision) ||
    67	      !request.requiredHumanActorId) throw new PullRequestError("invalid_merge_request");
    68	  const before = await adapter.read(request.repository, request.nativeId);
    69	  if (!before) throw new PullRequestError("pr_missing");
    70	  validateObservation(before, request.repository, request.nativeId);
    71	  if (before.state === "merged") {
    72	    if (before.head.revision === request.headRevision && before.mergedRevision === request.headRevision) return before;
    73	    throw new PullRequestError("merge_identity_mismatch");
    74	  }
    75	  if (before.state !== "open") throw new PullRequestError("pr_closed");
