    const adapter = {
      repository: async () => repository,
      defaultBranch: async () => ({ repository, ref: "refs/heads/main", revision: base }),
      findByBranches: async () => draft,
      createDraft: async () => {
        creates++;
        draft = { repository, nativeId: "7", head: { repository, ref: "refs/heads/work", revision: sha },
          base: { repository, ref: "refs/heads/main", revision: base }, state: "open", draft: true,
          mergeable: null, mergeStrategy: "fast-forward-only" as const, requiredChecks: [],
          requiredApprovals: 0, reviews: [], discussionCount: 0, providerRevision: "revision-1" };
        throw new PullRequestError("create_outcome_unknown");
      }
    };
    const coordinator = new PullRequestDraftCoordinator({ effects,
      publication: () => ({ reportId: "report-1", projectId: "project-1", taskId: "task-1", state: "confirmed",
        repository, ref: "refs/heads/work", candidateRevision: sha }),
      binding: () => ({ id: "pr", projectId: "project-1", revision: 1, enabled: true,
        instanceId: "forge", repositoryId: "42" }),
