    const first = await coordinator.create("report-1");
    assert.equal(first.state, "confirmed");
    assert.equal(first.nativePrId, "7");
    assert.equal((await coordinator.create("report-1")).effectId, first.effectId);
    assert.equal(creates, 1);
  } finally { sqlite.close(); }
});

